lycamobile.co.uk.apply:
const coupon = document.querySelector('#coupon_code, #discount-code')
const btn_coupon = document.querySelector('#tid .apply_button, button.action.apply, button.action-apply');
try{
  coupon.dispatchEvent(new Event('input', { bubbles: true }));
  coupon.dispatchEvent(new Event('keyup'));
  coupon.dispatchEvent(new Event('blur'));
  coupon.dispatchEvent(new Event('focus'));
  coupon.dispatchEvent(new Event('change'));

  btn_coupon.click();
}catch(e){}

wig-supplier.com.apply:
try{
  document.querySelector('#coupon_code').dispatchEvent(new Event('input', {bubbles: true}));
  document.querySelector('#coupon_code').dispatchEvent(new Event('change'));
  document.querySelector('button.action.apply.primary').click();
}catch(e){
  document.querySelector('input#discount-code').dispatchEvent(new Event('input', {bubbles: true}));
  document.querySelector('input#discount-code').dispatchEvent(new Event('change'));
  document.querySelector('button.action.action-apply').click();
}

